// boundaryStubs are the shim stubs testdata/boundary/guest.s calls, generated by the emitter.
var boundaryStubs = [][2]string{
	{"_stub_sceFiberRun", "shim_sceFiberRun"},
	{"_stub_sceFiberSwitch", "shim_sceFiberSwitch"},
	{"_stub_sceFiberReturnToThread", "shim_sceFiberReturnToThread"},
	{"_stub_test_noop", "shim_test_noop"},
	{"_stub_test_wait_signal", "shim_test_wait_signal"},
	{"_stub_test_set_gprs", "shim_test_set_gprs"},
	{"_stub_test_xmm", "shim_test_xmm"},
	{"_stub_test_fpcr", "shim_test_fpcr"},
	{"_stub_pthread_create", "shim_pthread_create"},
	{"_stub_pthread_join", "shim_pthread_join"},
	{"_stub___tls_get_addr", "shim___tls_get_addr"},
	{"_stub_test_record_ctx", "shim_test_record_ctx"},
}

// boundaryRuntimeSources are the runtime files the boundary tests run against, compiled with
// the flags of the game build (pkg/cli: -O2 -ffp-contract=off).
var boundaryRuntimeSources = []string{
	"core/recomp_runtime.c",
	"kernel/threading/ps4_threading.c",
	"kernel/threading/ps4_stall_profile.c",
	"modules/libSceFiber/ps4_fiber.c",
	"modules/libkernel/ps4_kernel_sys.c",
}

// liftedHelperFns are guest functions around one instruction the lifter lowers to a runtime
// helper call (testdata/boundary/harness.c test_helpers): every vector register gets 0x40+n in
// all bytes and NZCV = 0x6 (Z, C) before it; all 32 vector registers, rcx and NZCV are stored
// to the result block afterwards. The functions use YMM, so v16-v31 hold live upper halves.
var liftedHelperFns = []struct {
	sym  string
	code []byte
	res  uint64
}{
	{"_guest_lifted_vpcmpistri", []byte{0xc4, 0xe3, 0x79, 0x63, 0xd3, 0x38}, 0x1003000},       // vpcmpistri xmm2, xmm3, 0x38
	{"_guest_lifted_vaeskeygenassist", []byte{0xc4, 0xe3, 0x79, 0xdf, 0xe5, 0x01}, 0x1003400}, // vaeskeygenassist xmm4, xmm5, 1
}

func writeLiftedHelperFns(t *testing.T, path string) {
	t.Helper()
	var b strings.Builder
	b.WriteString(guestTextSection + "\n.p2align 2\n\n")
	li := func(reg string, v uint64) {
		fmt.Fprintf(&b, "    movz %s, #0x%x\n    movk %s, #0x%x, lsl #16\n", reg, v&0xffff, reg, v>>16)
	}
	for i, f := range liftedHelperFns {
		inst, err := x86asm.Decode(f.code, 64)
		if err != nil {
			t.Fatal(err)
		}
		addr := uint64(0x500000 + i*0x100)
		fn := &disasm.Function{EntryAddr: addr, UsesYmm: true}
		lines, err := lifter.NewArm64Lifter(nil).LiftInstructionToBuf(disasm.Instruction{Address: addr, Inst: inst},
			addr+uint64(inst.Len), fn, nil)
		if err != nil {
			t.Fatal(err)
		}
		fmt.Fprintf(&b, ".globl %s\n%s:\n    str x30, [sp, #-16]!\n", f.sym, f.sym)
		for v := 0; v < 32; v++ {
			fmt.Fprintf(&b, "    movi v%d.16b, #0x%x\n", v, 0x40+v)
		}
		b.WriteString("    movz x16, #0x6000, lsl #16\n    msr nzcv, x16\n")
		fmt.Fprintf(&b, "    // %s\n%s\n", inst.String(), strings.Join(lines, "\n"))
		b.WriteString("    mrs x0, nzcv\n")
		li("x16", f.res)
		b.WriteString("    add x16, x28, x16\n")
		for v := 0; v < 32; v += 2 {
			fmt.Fprintf(&b, "    stp q%d, q%d, [x16, #%d]\n", v, v+1, v*16)
		}
		b.WriteString("    add x16, x16, #512\n    stp x21, x0, [x16]\n")
		b.WriteString("    ldr x16, [x28, x26]\n    add x26, x26, #8\n    ldr x30, [sp], #16\n    ret\n\n")
	}
	if err := os.WriteFile(path, []byte(b.String()), 0o644); err != nil {
		t.Fatal(err)
	}
}

// buildBoundaryHarness links the emitted trampoline and shim stubs, the lifted helper-call
// functions, guest.s, harness.c and the runtime sources into one host program.
func buildBoundaryHarness(t *testing.T) string {
	t.Helper()
	if _, err := exec.LookPath("clang"); err != nil {
		t.Skip("clang not found")
	}
	dir := t.TempDir()
	tramp := filepath.Join(dir, "trampoline_arm64.s")
	if err := (&AsmEmitter{}).EmitTrampoline(tramp); err != nil {
		t.Fatal(err)
	}
	var stubs bytes.Buffer
	stubs.WriteString(guestTextSection + "\n.p2align 2\n\n")
	for _, s := range boundaryStubs {
		writeShimStub(&stubs, s[0], s[1])
	}
	stubPath := filepath.Join(dir, "stubs_gen.s")
	if err := os.WriteFile(stubPath, stubs.Bytes(), 0o644); err != nil {
		t.Fatal(err)
	}

	rt, err := filepath.Abs("../runtime")
	if err != nil {
		t.Fatal(err)
	}
	args := []string{"-target", "arm64-apple-darwin", "-mcpu=apple-m1", "-DRECOMP_ARM64_ASM=1", "-O2",
		"-ffp-contract=off", "-Wno-format", "-Wno-parentheses-equality"}
	err = filepath.WalkDir(rt, func(p string, d os.DirEntry, err error) error {
		if err == nil && d.IsDir() {
			args = append(args, "-I"+p)
		}
		return err
	})
	if err != nil {
		t.Fatal(err)
	}
	lifted := filepath.Join(dir, "lifted_gen.s")
	writeLiftedHelperFns(t, lifted)
	td, _ := filepath.Abs("testdata/boundary")
	args = append(args, filepath.Join(td, "harness.c"), filepath.Join(td, "stubs.c"), filepath.Join(td, "guest.s"),
		tramp, stubPath, lifted)
	for _, s := range boundaryRuntimeSources {
		args = append(args, filepath.Join(rt, s))
	}
	bin := filepath.Join(dir, "boundary_harness")
	args = append(args, "-o", bin)
	if out, err := exec.Command("clang", args...).CombinedOutput(); err != nil {
		t.Fatalf("building the boundary harness: %v\n%s", err, out)
	}
	return bin
}

// TestGuestStateBoundary runs the guest-state boundary cases of testdata/boundary/harness.c:
// guest code calls shims through the emitted bridge, and fibers switch inside shims.
func TestGuestStateBoundary(t *testing.T) {
	bin := buildBoundaryHarness(t)
	cases := []struct {
		name, arg string
		env       []string
	}{
		{"fiber/coroutines", "fiber", nil},
		{"fiber/threads", "fiber", []string{"PS4_FIBER_THREADS=1"}},
		{"exception-handler-in-shim", "exception", nil},
		{"shim-sets-gprs", "gprs", nil},
		{"xmm-arguments-and-results", "xmm", nil},
		{"enter-guest-keeps-d8-d15", "callee-saved-fp", nil},
		{"fpcr", "fpcr", nil},
		{"helper-calls-keep-registers", "helpers", nil},
		{"thread-start-and-tls", "thread", nil},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			cmd := exec.Command(bin, c.arg)
			cmd.Env = append(os.Environ(), c.env...)
			out, err := cmd.CombinedOutput()
			if err != nil || !strings.Contains(string(out), "PASS "+c.arg) {
				t.Fatalf("%s: %v\n%s", c.arg, err, out)
			}
		})
	}
}
